(function () {
    if (window.__customSafeZoneInitialized) return;
    window.__customSafeZoneInitialized = true;

    const config = {
        text: ' ',
        iconImageURL: 'https://i.postimg.cc/T3nkT8sB/zone2.png',
        backgroundImage: 'https://i.postimg.cc/T3nkT8sB/zone2.png'    };
    window.forceSafeZoneUpdate = function() {
        updateSafeZoneElements();
    };

    const safeZoneStyles = document.createElement('style');
    safeZoneStyles.id = 'custom-safe-zone-styles';
    safeZoneStyles.textContent = `
        .hud-radmir-radar__safe-zone {
            position: absolute;
            top: -5.5vh;
            left: 50%;
            transform: translateX(-50%);
            display: flex;
            align-items: center;
            gap: 1vh;
            padding: 1vh 2vh;
            font-family: 'GothamPro Bold', sans-serif;
            font-size: 1.85vh;
            color: #f5eded;
            z-index: 10;
            pointer-events: none;
        }
        
        .hud-radmir-radar__safe-zone__bg {
            position: absolute;
            width: 100%;
            height: 100%;
            top: 0;
            left: 0;
            background: ${config.backgroundImage || 'linear-gradient(90deg, rgba(101, 196, 102, 0) 0%, rgba(255, 255, 255, 0.8) 50%, rgba(101, 196, 102, 0) 100%)'};
            filter: blur(1.5vh);
            border-radius: 2vh;
            z-index: -1;
        }
        
        .hud-radmir-radar__safe-zone__icon {
            width: 2.5vh;
            height: auto;
            flex-shrink: 0;
            z-index: 1;
        }
        
        .hud-radmir-radar__safe-zone__text {
            white-space: nowrap;
            z-index: 1;
            text-shadow: 0 0.2vh 0.4vh rgba(0, 0, 0, 0.5);
        }
    `;
    document.head.appendChild(safeZoneStyles);
    function updateSafeZoneElements() {
        const safeZoneContainers = document.querySelectorAll('.hud-radmir-radar__safe-zone');
        safeZoneContainers.forEach(container => {
            container.innerHTML = '';
            const bgDiv = document.createElement('div');
            bgDiv.className = 'hud-radmir-radar__safe-zone__bg';
            if (config.backgroundImage) {
                bgDiv.style.background = config.backgroundImage;
            }
            container.appendChild(bgDiv);
            const imgElement = document.createElement('img');
            imgElement.src = config.iconImageURL.trim();
            imgElement.className = 'hud-radmir-radar__safe-zone__icon';
            imgElement.alt = 'Safe Zone Icon';
            imgElement.onerror = function() {
                console.error('Failed to load image:', config.iconImageURL);
            };
            container.appendChild(imgElement);

            const textSpan = document.createElement('span');
            textSpan.className = 'hud-radmir-radar__safe-zone__text';
            textSpan.textContent = config.text;
            container.appendChild(textSpan);
        });
    }
    const observer = new MutationObserver((mutations) => {
        for (const mutation of mutations) {
            if (mutation.addedNodes.length > 0) {
                mutation.addedNodes.forEach(node => {
                    if (node.nodeType === Node.ELEMENT_NODE) {
                        if (node.classList?.contains('hud-radmir-radar__safe-zone') ||
                            node.querySelector?.('.hud-radmir-radar__safe-zone')) {
                            setTimeout(updateSafeZoneElements, 0);
                        }
                    }
                });
            }
        }
    });
    observer.observe(document.body, {
        childList: true,
        subtree: true
    });
    setTimeout(updateSafeZoneElements, 500);
})();
(function () {
    if (window.__greenZoneFixed) return;
    window.__greenZoneFixed = true;
    const hideStyle = document.createElement('style');
    hideStyle.id = '__hideGreenZoneStyle';
    hideStyle.textContent = `
        [class*="green"].__hidden-by-script,
        [class*="zone"].__hidden-by-script,
        .hud-radmir-greenzone.__hidden-by-script,
        .green-zone.__hidden-by-script,
        .gzone.__hidden-by-script,
        .map__greenzone.__hidden-by-script,
        .map-greenzone.__hidden-by-script,
        svg[class*="zone"].__hidden-by-script,
        svg[class*="green"].__hidden-by-script,
        #app .hud-circle-green.__hidden-by-script,
        #app .hud-round-green.__hidden-by-script {
            position: relative !important;
            transform: translateX(-100vw) !important;
            visibility: hidden !important;
            opacity: 0 !important;
        }
    `;
    document.head.appendChild(hideStyle);
    function hideOriginalZones() {
        const selectors = [
            '[class*="green"]',
            '[class*="zone"]',
            '.hud-radmir-greenzone',
            '.green-zone',
            '.gzone',
            '.map__greenzone',
            '.map-greenzone',
            'svg[class*="zone"]',
            'svg[class*="green"]',
            '#app .hud-circle-green',
            '#app .hud-round-green'
        ];
        const all = document.querySelectorAll(selectors.join(', '));
        all.forEach(el => el.classList.add('__hidden-by-script'));
    }
    function showOriginalZones() {
        const all = document.querySelectorAll('.__hidden-by-script');
        all.forEach(el => el.classList.remove('__hidden-by-script'));
    }
    const customZone = document.createElement('div');
    customZone.className = 'Old-Fixed-ZZ';
    customZone.innerHTML = `
        <img src="data:image/png;base64,"
    style="width: 3.6vh; height: 4.5vh;">
    `;
    customZone.style.cssText = `
        position: absolute;
        left: 2%;
        bottom: 3vh;
        transform: translateX(-50%);
        display: none;
        z-index: 999999;
    `;
    document.body.appendChild(customZone);

    let attempts = 0;
    const maxAttempts = 100;
    const initInterval = setInterval(() => {
        attempts++;
        if (attempts > maxAttempts) {
            clearInterval(initInterval);
            console.warn('Green zone initialization timeout: window.interface not available');
            return;
        }
        if (typeof window.interface !== 'function') return;
        const hud = window.interface('Hud');
        if (!hud || !hud.showGreenZoneTab || !hud.hideGreenZoneTab) return;
        clearInterval(initInterval);

        const origShow = hud.showGreenZoneTab;
        const origHide = hud.hideGreenZoneTab;

        hud.showGreenZoneTab = function () {
            customZone.style.display = '';
            return origShow.apply(this, arguments);
        };
        hud.hideGreenZoneTab = function () {
            customZone.style.display = 'none';
            return origHide.apply(this, arguments);
        };
    }, 100);
})();